WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND serial_id=#{serial}

UPDATE local_serial
SET balance_id=#{balanceId}, state=#{state}, registry_state=#{registryState}, registry_error=#{registryError}, owner_epoch=#{epoch}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND serial_id=#{serial}

mapper.select:
SELECT serial_id, state, owner_epoch, sku_id, lot_id
FROM local_serial
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND balance_id=#{balanceId}
AND state IN ('AUTHORIZED','HOLD_RECEIVED','EXCEPTION','RECEIVING')
ORDER BY serial_id FOR UPDATE

SELECT COUNT(*)
FROM local_serial s JOIN count_line l ON l.enterprise_id=s.enterprise_id
AND l.warehouse_id=s.warehouse_id
AND l.balance_id=s.balance_id
WHERE s.enterprise_id=#{enterpriseId}
AND s.warehouse_id=#{warehouseId}
AND l.count_plan_id=#{planId}
AND s.state='MISSING_PENDING'

