  receipt_operation_id=#{operation},owner_epoch=#{epoch},registry_error=NULL,transfer_id=NULL,source_release_ref=NULL,
  version=version+1,updated_at=#{now}
WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND serial_id=#{serial} AND version=#{version}
  AND state IN ('INTENDED','MISSING')
